if ($KeepLatestN -gt 0) {
    $groups = $items | Group-Object -Property WorkflowRunId
    foreach ($g in $groups) {
        # Newest first; Name as a deterministic tie-breaker.
        $ordered = $g.Group | Sort-Object -Property @{Expression = 'CreatedAt'; Descending = $true},
